sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    //MSSTRESURY-160
    if (isLoading) return;
    var userID = g_user.userID;
    var isManager = g_scratchpad.isManager;
    var assignToGA = null;
    // MSSTRESURY-452
    if (g_scratchpad.taskAlreadyAssignTo[newValue]) {
        g_form.addErrorMessage("Same user can't be assigned to both maker and checker task");
        setTimeout(function() {
            g_form.setValue("assigned_to", '');
        }, 0);
        return;
    }
    if (newValue == '' && oldValue != '') {
        if (!isManager && oldValue == userID) {
            g_form.save();
            g_aw.closeRecord();
        } else if (isManager) {
            // MSSTRESURY-700
            assignToGA = new GlideAjax('MSS_Treasury_Client_Utils');
            assignToGA.addParam('sysparm_name', 'updateAssignToNullForClient');
            assignToGA.addParam('sysparm_task_sys_id', g_form.getUniqueValue());
            assignToGA.getXMLAnswer(function() {});
        }
        return;
    }
    if (newValue != '') { // WORKSPACE
        var assigned = g_form.getDisplayValue("assigned_to");
        if (newValue != userID && oldValue == userID) {
            if (!isManager) {
                g_form.addErrorMessage('You can only assign the task to yourself.');
                g_form.reload();
                return;
            }

        }
        g_form.save();
        g_form.addInfoMessage('Task is now assigned to ' + assigned);

    }


}
